// 나쁨 — 반복마다 강제 레이아웃
for (const el of els) el.style.width = el.offsetWidth / 2 + 'px';

// 좋음 — 읽기 단계 / 쓰기 단계
const ws = els.map((el) => el.offsetWidth);
els.forEach((el, i) => { el.style.width = ws[i] / 2 + 'px'; });

// 프레임 단위로 나눌 때
requestAnimationFrame(() => { /* 여기서 쓰기 */ });

/* 나쁨 */
.card { transition: left .3s, width .3s; }

/* 좋음 */
.card { transition: transform .3s, opacity .3s; }
.card.is-open { transform: translateX(200px) scale(1.05); opacity: 1; }

/* 크기 변화도 scale 로 표현할 수 있는 경우가 많다 */

// ① 시간 예산을 두고 나눠서 처리
function chunk(items, work) {
  let i = 0;
  (function run() {
    const end = performance.now() + 8;          // 프레임 절반만 쓴다
    while (i < items.length && performance.now() < end) work(items[i++]);
    if (i < items.length) requestAnimationFrame(run);
  })();
}

// ② 급하지 않은 일은 한가할 때
requestIdleCallback(() => sendAnalytics());

// ③ 계산이 정말 무거우면 워커로 (cs-os 7장)

let latest = 0, ticking = false;
window.addEventListener('scroll', () => {
  latest = window.scrollY;              // 값만 저장한다 (싸다)
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(() => {         // 실제 작업은 프레임에 한 번
    header.classList.toggle('is-stuck', latest > 100);
    ticking = false;
  });
}, { passive: true });

// 「보이면 처리」는 관찰자에게 맡기는 편이 더 싸다
new IntersectionObserver(onVisible).observe(el);

// web-vitals 라이브러리 (또는 PerformanceObserver 직접)
import { onLCP, onCLS, onINP } from 'web-vitals';
onLCP(send); onCLS(send); onINP(send);

function send(metric) {
  navigator.sendBeacon('/rum', JSON.stringify({
    name: metric.name, value: metric.value, id: metric.id,
  }));
}

// 개발자도구 Lighthouse 는 「실험실」 값 — 참고용이지 진실이 아니다

@font-face {
  font-family: 'Pretendard';
  src: url('/fonts/pretendard-subset.woff2') format('woff2');
  font-display: swap;                 /* 일단 보여 주고 나중에 바꾼다 */
  unicode-range: U+AC00-D7A3, U+0020-007E;   /* 필요한 글자만 */
}

/* 대체 글꼴의 크기를 맞춰 바뀔 때의 밀림을 줄인다 */
@font-face {
  font-family: 'Pretendard Fallback';
  src: local('Apple SD Gothic Neo'), local('Malgun Gothic');
  size-adjust: 96%;
}
